(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.TaskWorkshop=api;})(typeof window==='undefined'?globalThis:window,function(){
'use strict';
const kinds=['sort','order','choose','number','matrix','allocate','rate','edit'];
function equalSet(a,b){return Array.isArray(a)&&new Set(a).size===a.length&&a.length===b.length&&b.every(x=>a.includes(x));}
function numeric(x){return(typeof x==='number'||typeof x==='string'&&x.trim()!=='')&&Number.isFinite(Number(x));}
function grade(round,answer){if(!round||!answer||typeof answer!=='object')return false;
 if(round.type==='sort')return round.items.every(i=>answer.placements?.[i.id]===i.target)&&Object.keys(answer.placements||{}).every(id=>round.items.some(i=>i.id===id));
 if(round.type==='order')return Array.isArray(answer.order)&&answer.order.length===round.items.length&&round.expected.every((id,i)=>answer.order[i]===id);
 if(round.type==='choose')return equalSet(answer.selected,round.expected);
 if(round.type==='number'||round.type==='edit'||round.type==='rate')return round.fields.every(f=>{const a=answer.values?.[f.id];return typeof f.expected==='number'?numeric(a)&&Math.abs(Number(a)-f.expected)<=(f.tolerance||0):typeof a==='string'&&a.trim()===f.expected;});
 if(round.type==='matrix')return equalSet(answer.selected,round.expected);
 if(round.type==='allocate'){if(!Array.isArray(answer.selected)||new Set(answer.selected).size!==answer.selected.length)return false;const cards=answer.selected.map(id=>round.items.find(i=>i.id===id));if(cards.some(c=>!c||c.blocked))return false;const cost=cards.reduce((n,c)=>n+c.cost,0),value=cards.reduce((n,c)=>n+c.value,0);return cost<=round.budget&&value>=round.minimumValue&&(round.required||[]).every(id=>answer.selected.includes(id));}return false;
}
function signature(plan){const text=JSON.stringify(plan);let h=2166136261;for(let i=0;i<text.length;i++)h=Math.imul(h^text.charCodeAt(i),16777619);return 'w1-'+(h>>>0).toString(16)+'-'+text.length;}
function fresh(plan){return{v:1,signature:signature(plan),round:0,attempts:0,answers:[],draft:{}};}
function progress(s,sec){s.workshops??={};let p=s.workshops[sec.id];if(!p||p.signature!==signature(sec.activity))p=s.workshops[sec.id]=fresh(sec.activity);return p;}
function submit(s,sec,answer){const p=progress(s,sec),r=sec.activity.rounds[p.round];if(!r)return false;p.attempts++;if(!grade(r,answer))return false;p.answers.push(JSON.parse(JSON.stringify(answer)));p.round++;p.draft={};return true;}
function mastered(s,sec){const p=s.workshops?.[sec.id];return!!p&&p.signature===signature(sec.activity)&&p.round===sec.activity.rounds.length&&p.answers.length===p.round&&p.answers.every((a,i)=>grade(sec.activity.rounds[i],a));}
function validPlan(plan){try{const text=t=>t&&['zh','en'].every(k=>typeof t[k]==='string'&&t[k].trim()&&t[k].length<=6000),id=x=>typeof x==='string'&&/^[a-zA-Z0-9_.-]{1,80}$/.test(x),list=a=>Array.isArray(a)&&a.length>0&&a.every(i=>i&&id(i.id)&&text(i.text))&&new Set(a.map(i=>i.id)).size===a.length;if(!plan||!/^([a-z][a-z0-9-]{0,40})$/.test(plan.kind)||!text(plan.title)||plan.version!==1||typeof plan.kind!=='string'||!plan.title?.zh||!plan.title?.en||!Array.isArray(plan.rounds)||!plan.rounds.length||plan.rounds.length>20)return false;if(new Set(plan.rounds.map(r=>r?.id)).size!==plan.rounds.length)return false;return plan.rounds.every(r=>{if(!r||!kinds.includes(r.type)||!id(r.id)||!text(r.prompt)||!text(r.reason)||!r.prompt?.zh||!r.prompt?.en||!r.reason?.zh||!r.reason?.en||!Array.isArray(r.skills)||!r.skills.length||!r.skills.every(id))return false;if(r.type==='sort')return list(r.items)&&r.items.length>1&&r.items.length<=20&&list(r.bins)&&r.bins.length>=2&&r.bins.length<=10&&new Set(r.items.map(x=>x.id)).size===r.items.length&&r.items.every(i=>i.id&&i.text?.zh&&i.text?.en&&r.bins.some(b=>b.id===i.target));if(r.type==='order')return list(r.items)&&r.items.length>1&&r.items.length<=12&&new Set(r.items.map(x=>x.id)).size===r.items.length&&equalSet(r.expected,r.items.map(i=>i.id));if(r.type==='choose')return list(r.options)&&r.options.length>=2&&r.options.length<=20&&r.expected.length>0&&new Set(r.options.map(x=>x.id)).size===r.options.length&&equalSet(r.expected,[...new Set(r.expected)])&&r.expected.every(id=>r.options.some(o=>o.id===id));if(['number','edit','rate'].includes(r.type))return Array.isArray(r.fields)&&r.fields.length>0&&r.fields.length<=20&&new Set(r.fields.map(x=>x.id)).size===r.fields.length&&r.fields.every(f=>id(f.id)&&text(f.label)&&((typeof f.expected==='number'&&Number.isFinite(f.expected))||typeof f.expected==='string')&&(f.tolerance===undefined||Number.isFinite(f.tolerance)&&f.tolerance>=0)&&(r.type!=='rate'||Number.isFinite(f.min)&&Number.isFinite(f.max)&&f.min<=f.expected&&f.expected<=f.max)&&(r.type!=='number'||typeof f.expected==='number'));if(r.type==='matrix')return list(r.rows)&&list(r.columns)&&r.rows.length<=10&&r.columns.length<=10&&equalSet(r.expected,[...new Set(r.expected)])&&r.expected.every(id=>r.rows.some(row=>r.columns.some(col=>id===row.id+':'+col.id)));if(r.type==='allocate')return Number.isFinite(r.budget)&&r.budget>=0&&Number.isFinite(r.minimumValue)&&list(r.items)&&r.items.length>1&&r.items.length<=15&&r.items.every(i=>i.id&&Number.isFinite(i.cost)&&i.cost>=0&&Number.isFinite(i.value)&&i.value>=0)&&(r.required||[]).every(id=>r.items.some(i=>i.id===id))&&Array.from({length:2**r.items.length},(_,mask)=>r.items.filter((_,i)=>mask&(1<<i)).map(i=>i.id)).some(selected=>grade(r,{selected}));return false;});}catch{return false;}}
function validate(s,course){if(s.workshops===undefined)return true;if(!s.workshops||typeof s.workshops!=='object'||Array.isArray(s.workshops))return false;return Object.entries(s.workshops).every(([id,p])=>{const sec=course.chapters.flatMap(c=>c.sections).find(sec=>sec.id===id);if(!sec?.activity||!p||p.v!==1||!Number.isSafeInteger(p.attempts)||p.attempts<0||!Number.isInteger(p.round)||p.round<0||!Array.isArray(p.answers)||p.answers.length!==p.round||p.attempts<p.round||typeof p.signature!=='string'||!p.draft||typeof p.draft!=='object'||Array.isArray(p.draft))return false;if(p.signature!==signature(sec.activity))return true;return p.round<=sec.activity.rounds.length&&p.answers.every((a,i)=>grade(sec.activity.rounds[i],a));});}
return{kinds,grade,fresh,progress,submit,mastered,validPlan,validate,signature};
});
